function priceSpecs(kind='home'){
 if(kind==='home')return [
  {title:'Полное погружение',subtitle:'Когда одного раунда уже мало',time:'60 МИНУТ',rates:gameRates,per:'за игрока',features:['Несколько игровых раундов','Смена сценариев','Инструктаж и оборудование','Могут присоединиться другие игроки'],button:'Выбрать погружение',featured:true,duration:'60',format:'game'},
  {title:'Закрытое мероприятие',subtitle:'Арена недоступна другим гостям, пока вы играете',time:'1 ЧАС',rates:privateRates,per:'за компанию',features:['Игра и смена игровых карт','До 10 участников','Персональный инструктор'],button:'Спланировать событие',duration:'60',format:'private'},
  {...priceSpecs('birthday')[2],button:'Выбрать праздник'}
 ];
 const birth=kind==='birthday';
 return [
  {title:birth?'Старт праздника':'Одна команда',subtitle:birth?'Небольшая компания, большие эмоции':'Выйти за рамки рабочего дня',time:'1 ЧАС',duration:'60',features:['До 10 игроков',birth?'Фиксированный 1 час игры + лаунж для отдыха и торта':'Фиксированный 1 час игры + лаунж для отдыха и общения','Никаких расчётов по минутам','Персональный инструктор']},
  {title:'День за гранью',subtitle:'Больше игры, больше воспоминаний',time:'2 ЧАСА',duration:'120',featured:true,features:['До 10 игроков','Всё, что нужно для праздника, в одном пакете: 2 часа на арене и время в лаунж-зоне','Sony PlayStation','Персональный инструктор',...(birth?['Подарки участникам','Подарок имениннику — сертификат на следующее посещение']:[])]},
  {title:'Своя вселенная',subtitle:'Праздник с особым сценарием',time:'3 ЧАСА',duration:'180',features:['До 10 игроков','Хватит на всё: 3 часа — и на игру, и на торт','Sony PlayStation','Персональный инструктор','Арена и лаунж в одном пакете, без спешки и поминутных расчётов','Замена игрока на арене +500 ₽',...(birth?['Подарки участникам','Подарок имениннику — сертификат на следующее посещение']:[])]}
 ].map(p=>({...p,rates:eventRates[p.duration],per:'за компанию',format:kind,button:'Выбрать пакет'}));
}
function priceCards(kind='home'){
 return priceSpecs(kind).map(p=>`<article class="price-card ${p.featured?'featured':''}">${p.featured?'<span class="price-flag">ВЫБОР КОМАНДЫ</span>':''}<div class="eyebrow">${p.time}</div><h3>${p.title}</h3><p class="price-desc">${p.subtitle}</p><div class="price-rates">${p.rates.map((price,i)=>`<div class="price-rate"><span>${i?'ПТ–ВС':'ПН–ЧТ'}</span><strong class="${price===null?'price-unconfirmed':''}">${price===null?'Уточните у администратора':money(price)}</strong></div>`).join('')}<small>${p.per}</small></div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="btn ${p.featured?'':'btn-outline'}" data-book data-format="${p.format}" data-duration="${p.duration}" data-package="${esc(p.title)}">${p.button} ${icon('arrow')}</button></article>`).join('');
}
function pricing(kind='home'){const event=kind!=='home';return `<section class="section prices-section" id="prices"><div class="wrap"><div class="eyebrow">${event?'Выбери свой формат праздника':'Найди свой формат'}</div><div class="section-head"><h2>${kind==='home'?'СКОЛЬКО СТОИТ<br><em>ДРУГАЯ РЕАЛЬНОСТЬ?</em>':kind==='birthday'?'ТАРИФЫ ДНЯ РОЖДЕНИЯ<br><em>В VR</em>':'ТАРИФЫ<br><em>КОРПОРАТИВОВ</em>'}</h2><p class="games-sub">Цены будней и выходных<br>сразу перед глазами</p></div><div class="price-grid ${event?'':'price-grid-home'}" id="price-grid">${priceCards(kind)}</div>${event?`<div class="package-included"><h3>В каждом пакете</h3><ul><li>Оборудованная лаунж-зона: кулер, чайник, микроволновка, чайные принадлежности</li><li>Праздничная сервировка стола на всех гостей</li>${kind==='birthday'?'<li>Электронные пригласительные для гостей</li>':''}</ul><p>${kind==='birthday'?'Ваш день, ваша арена: никаких случайных игроков рядом — только ваша команда в центре событий':'Вся арена — ваша территория: играйте, побеждайте, не отвлекаясь на других'}</p></div>`:''}<p class="pricing-note">${icon('info')}Оборудование и инструктаж включены. ${event?'Стоимость указана за компанию до 10 игроков':'Для закрытого мероприятия стоимость указана за компанию до 10 игроков'}</p></div></section>`}
function stepsSection(){return `<section class="section steps-section"><div class="wrap"><div class="eyebrow">От тебя до новой реальности</div><div class="section-head"><h2>ТРИ ШАГА <em>ЗА ГРАНЬ</em></h2></div><div class="steps"><div class="step"><span class="step-number">01 /</span><h3>Собери свою команду</h3><p>Зови друзей, семью или коллег. А можно начать приключение в одиночку.</p></div><div class="step"><span class="step-number">02 /</span><h3>Выбери время и игру</h3><p>Найди сценарий по настроению и оставь заявку на удобный сеанс.</p></div><div class="step"><span class="step-number">03 /</span><h3>Оставь реальность снаружи</h3><p>Приходи за 15 минут до игры. Всё покажем, настроим и отправим в новый мир.</p></div></div></div></section>`}
const demoReviews=[{name:'Алексей',kind:'Игра с друзьями',text:'Первый раз играли всей компанией. Сначала осваивались, а через пять минут уже прикрывали друг друга и строили планы на следующий раунд.'},{name:'Мария',kind:'День рождения',text:'Дети обсуждали игру весь вечер. Успели и побегать по виртуальному миру, и спокойно посидеть с тортом. Очень необычный формат праздника.'},{name:'Дмитрий',kind:'Корпоратив',text:'Собрали две команды из коллег. Оказалось, что за пределами офиса мы отлично дополняем друг друга. Финал турнира был особенно азартным.'}];
function reviewHTML(r,demo=true){return `<article class="review"><div class="review-top"><span class="stars" aria-label="5 из 5">★★★★★</span><span>${demo?'ПРИМЕР ОТЗЫВА':'ЛОКАЛЬНЫЙ ОТЗЫВ'}</span></div><blockquote>${esc(r.text)}</blockquote><div class="review-person"><span class="avatar">${esc(r.name.slice(0,1))}</span><div>${esc(r.name)}<small>${esc(r.kind||'Посещение арены')}</small></div></div></article>`}
function reviewsSection(){const local=readStore(key,[]).filter(r=>r.type==='Отзыв').slice(-3).reverse().map(r=>reviewHTML({name:r.name,text:r.message,kind:r.kind},false)).join('');return `<section class="section reviews-section" id="reviews"><div class="wrap"><div class="eyebrow">После снятого шлема</div><div class="section-head"><h2>ЭМОЦИИ <em>ОСТАЮТСЯ</em></h2><button class="text-link" style="background:none;border-width:0 0 1px" data-action="review">Оставить отзыв ${icon('arrow')}</button></div><div class="review-grid" id="review-grid">${local}${demoReviews.map(r=>reviewHTML(r)).join('')}</div></div></section>`}
function faqSection(kind='home'){return `<section class="section" id="faq"><div class="wrap faq-inner"><div class="faq-copy"><div class="eyebrow">Перед погружением</div><h2>ЕСТЬ ВОПРОСЫ?<br><em>ЕСТЬ ОТВЕТЫ</em></h2><p>Всё, что нужно знать перед первым визитом. А с остальным поможет администратор.</p><button class="text-link" style="background:none;border-width:0 0 1px" data-action="callback">Задать свой вопрос ${icon('arrow')}</button></div><div class="faq-list">${faq.map(([q,a],i)=>`<details${i===0?' open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`}
function blogSection(){return `<section class="section blog-section" id="blog"><div class="wrap"><div class="eyebrow">По ту сторону привычного</div><div class="section-head"><h2>НОВОСТИ <em>ДРУГОГО МИРА</em></h2><span class="muted small">Демонстрационные материалы</span></div><div class="blog-grid">${articles.map((a,i)=>`<button class="blog-card" data-action="article" data-index="${i}"><div class="blog-visual"><img src="/za-granyu-vr-arena/assets/${a.image}" alt="${esc(a.title)}" loading="lazy" width="600" height="300"><span class="tag">${a.category}</span></div><span class="blog-date">${a.date}</span><h3>${a.title} ${icon('arrow')}</h3></button>`).join('')}</div></div></section>`}
function contacts(){return `<section class="contact-section" id="contacts"><div class="wrap contact-inner"><div class="contact-copy"><div class="eyebrow">Точка входа в другой мир</div><h2>ВСТРЕТИМСЯ <em>ЗА ГРАНЬЮ</em></h2><div class="contact-info"><div><small>Адрес</small><p>${esc(venueAddress)}</p></div><div><small>Телефон · тестовый номер</small><a href="tel:+73852000000">+7 (3852) 00-00-00</a></div><div><small>Время работы</small><p>Ежедневно с 10:00 до 22:00</p></div><div><small>Email · тестовый адрес</small><a href="mailto:hello@za-granyu.example">hello@za-granyu.example</a></div></div><button class="btn" data-book>Выбрать время игры ${icon('arrow')}</button><p class="small muted">Перед визитом уточните адрес и условия посещения у администратора</p></div><div class="yandex-map"><div class="yandex-map-heading">${icon('pin')}<div><strong>Мы на карте</strong><p>${esc(venueAddress)}</p></div></div><iframe src="${esc(venueMapEmbed)}" title="Яндекс Карты — ${esc(venueAddress)}" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade"></iframe><div class="yandex-map-footer"><span>Барнаул · проспект Ленина, 100</span><a class="text-link" href="${esc(venueMapUrl)}" target="_blank" rel="noopener noreferrer">Открыть Яндекс Карты ${icon('arrow')}</a></div></div></div></section>`}
function innerHero(kind){const birth=kind==='birthday';return `<section class="hero inner-hero ${birth?'birthday':'corporate'}"><div class="hero-art"${config[kind]?` style="background-image:url('/za-granyu-vr-arena/assets/${esc(config[kind])}')"`:''}></div><div class="wrap hero-inner"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/za-granyu-vr-arena/">Главная</a><span>/</span><a href="/za-granyu-vr-arena/#events">Мероприятия</a><span>/</span><span aria-current="page">${birth?'Дни рождения':'Корпоративы'}</span></nav><div class="eyebrow">${birth?'Твой день — твои правила':'Из коллег — в команду героев'}</div><h1>${birth?'ДЕНЬ РОЖДЕНИЯ<br>ЗА ГРАНЬЮ<span>ПРИВЫЧНОГО</span>':'ВМЕСТЕ<br>В ДРУГОЙ<span>РЕАЛЬНОСТИ</span>'}</h1><p class="hero-sub">${birth?'Командный опыт. Выбирай миссии на 2–10 человек: побеждайте вместе, поддерживайте друг друга, создавайте общие воспоминания':'Оставьте рабочие задачи за дверью. Здесь вас ждут командная миссия, азарт турнира и эмоции, которые объединяют'}</p><div class="hero-actions"><button class="btn" data-book data-format="${kind}" data-duration="120">${birth?'Спланировать праздник':'Собрать команду'} ${icon('arrow')}</button><a class="btn btn-outline" href="#prices">Посмотреть пакеты</a></div><div class="hero-badges"><span>${icon('users')} ${birth?'Для детей от 6 лет и взрослых':'Для команд от 2 человек'}</span><span>${icon('coffee')} Своя лаунж-зона${birth?' (чай, кофе, посуда)':''}</span><span>${icon('shield')} Всегда рядом инструктор</span></div></div></section>`}
function included(kind){const birth=kind==='birthday';const items=birth?[
 ['headset','Праздник внутри игры','Вы не наблюдатели — вы главные герои сценария','events.webp'],['users','Вся компания вместе','Командные раунды: победа — общая, эмоции — втрое ярче','battle.webp'],['coffee','Лаунж-зона','Подарки, торт и разговоры про приключение','lounge.webp'],['shield','Всё под контролем','Инструктор всё объяснит, поможет надеть очки и освоиться: даже если кто-то впервые в VR, через 5 минут он уже в игре','arena.webp']
 ]:[['trophy','Командный турнир','Несколько раундов, смена соперников и финальная командная миссия'],['move','Общая цель','Договаривайтесь, распределяйте роли и побеждайте вместе'],['coffee','Место для общения','Обсудите лучшие моменты игры в отдельной лаунж-зоне'],['shield','Организация на нас','Инструктор проведёт тренировку и поможет с игровым сценарием']];return `<section class="section"><div class="wrap"><div class="eyebrow">${birth?'Не просто ещё один праздник':'Новый опыт для вашей команды'}</div><div class="section-head"><h2>${birth?'ПРАЗДНИК БЕЗ ГРАНИЦ<br><em>ДЕНЬ РОЖДЕНИЯ НА VR-АРЕНЕ</em>':'ВМЕСТЕ В ДРУГОЙ<br><em>РЕАЛЬНОСТИ</em>'}</h2></div><div class="included-grid ${birth?'included-photos':''}">${items.map(([i,h,p,image])=>`<div class="included">${image?`<img src="/za-granyu-vr-arena/assets/${image}" alt="Концептуальная иллюстрация — ${h}" loading="lazy" width="600" height="400">`:icon(i)}<h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>`}
function schedule(kind){const birth=kind==='birthday';const items=[['00:00','Знакомимся с ареной','Встречаем гостей и показываем игровую и лаунж-зоны.'],['00:15','Готовимся к миссии','Подбираем сценарий, настраиваем шлемы и тренируемся.'],['00:30',birth?'Вперёд, за приключением':'Начинаем турнир',birth?'Играем, меняем команды и покоряем новую реальность.':'Играем раунды, меняем тактику и определяем победителей.'],['01:30',birth?'Торт, подарки, эмоции':'Обсуждаем лучшие моменты',birth?'Отмечаем праздник в лаунж-зоне и делаем общее фото.':'Отдыхаем после игры и сохраняем командное фото.']];return `<section class="section"><div class="wrap"><div class="eyebrow">Пример программы на 2 часа</div><div class="section-head"><h2>ТАК ПРОХОДИТ <em>${birth?'ТВОЙ ДЕНЬ':'ВАШ ВЫЗОВ'}</em></h2></div><div class="timeline">${items.map(([t,h,p])=>`<div class="timeline-item"><small>${t}</small><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div></section>`}
function innerBanner(kind){return `<section class="section" style="padding-top:0"><div class="wrap"><div class="inner-banner"><div><h2>СОЗДАДИМ <em>ВАШ СЦЕНАРИЙ</em></h2><p>Расскажи о компании и пожеланиях — соберём подходящий формат.</p></div><button class="btn" data-book data-format="${kind}" data-duration="120">Обсудить мероприятие ${icon('arrow')}</button></div></div></section>`}
function admin(){const list=readStore(key,[]);return `<section class="admin-page"><div class="wrap"><nav class="breadcrumbs"><a href="/za-granyu-vr-arena/">Главная</a><span>/</span><span aria-current="page">Демо-админка</span></nav><div class="eyebrow">Тестовый режим</div><h1>ЗАЯВКИ И НАСТРОЙКИ</h1><p class="muted small">Данные хранятся только в этом браузере. Это открытый демонстрационный интерфейс, который не предназначен для реальных персональных данных. Серверная база, авторизация и email-уведомления не подключены.</p><div class="admin-tools"><button class="btn btn-outline" data-action="export">Выгрузить JSON ${icon('arrow')}</button><button class="btn btn-outline" data-action="clear-requests">Очистить демо-заявки</button></div><div class="admin-table-wrap">${list.length?`<table class="admin-table"><thead><tr><th>Номер / дата</th><th>Тип / контакт</th><th>Детали</th><th>Статус</th></tr></thead><tbody>${list.slice().reverse().map(r=>`<tr><td>${esc(r.id)}<small>${new Date(r.created).toLocaleString('ru-RU',{timeZone:'Asia/Barnaul'})}</small></td><td>${esc(r.type)}<small>${esc(r.name)} · ${esc(r.phone||r.email||'')}</small></td><td>${r.format?esc(formatName(r.format))+'<small>'+esc(r.date)+' · '+esc(r.time)+' · '+esc(r.players)+' чел. · '+esc(r.duration)+' мин.</small>':''}<small>${esc(r.message||r.game||r.package||'—')}</small></td><td><select aria-label="Статус заявки ${esc(r.id)}" data-status="${esc(r.id)}">${['Новая','В работе','Завершена'].map(s=>`<option${r.status===s?' selected':''}>${s}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table>`:'<p class="admin-empty">Заявок пока нет. Заполни демо-форму записи, чтобы увидеть её здесь.</p>'}</div><form class="admin-config" id="config-form"><h2>Фоны страниц</h2><p class="muted small" style="margin-bottom:20px">Изменения видны только в этом браузере. Используются изображения из ваших референсов.</p><div class="form-grid">${[['home','Главная'],['birthday','Дни рождения'],['corporate','Корпоративы']].map(([k,label])=>`<label class="field"><span>${label}</span><select name="${k}">${[['','По умолчанию'],['hero.webp','VR-боец / синий'],['battle.webp','VR-команда'],['events.webp','Праздники'],['arena.webp','Интерьер арены'],['pattern.webp','Геометрия']].map(([v,l])=>`<option value="${v}"${config[k]===v?' selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><button class="btn" type="submit">Сохранить фоны ${icon('check')}</button></form></div></section>`}
function promoLauncher(){return `<button class="promo-tab" data-action="wheel" aria-label="Открыть колесо скидок" aria-haspopup="dialog" aria-controls="modal-root" aria-expanded="false"><span class="promo-tab-wheel" aria-hidden="true"><b>%</b></span><span class="promo-tab-title">Твоя скидка</span><span class="promo-tab-arrow" aria-hidden="true">‹</span></button>`}
function render(){document.title=page==='birthday'?'Дни рождения — За Гранью':page==='corporate'?'Корпоративы — За Гранью':page==='admin'?'Демо-админка — За Гранью':'За Гранью — VR-арена';let content=page==='home'?homeHero()+numbers()+gamesSection()+experience()+eventsSection()+pricing()+bookingSection()+stepsSection()+reviewsSection()+faqSection()+blogSection()+contacts():page==='admin'?admin():innerHero(page)+included(page)+pricing(page)+schedule(page)+innerBanner(page)+faqSection(page)+contacts();$('#app').innerHTML=header()+`<main id="main">${content}</main>`+footer()+(page==='admin'?'':promoLauncher());if($('#booking-form')){syncDurations();setBookingDate();updateEstimate();}}
render();
let lastFocus=null,slide=0,storyIndex=0,toastTimer,wheelTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(content,cls=''){if(!$('#modal-root').hasChildNodes())lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-btn modal-close" data-action="close" aria-label="Закрыть окно">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('locked');requestAnimationFrame(()=>$('.modal-close')?.focus());}
function closeModal(){$('.promo-tab')?.setAttribute('aria-expanded','false');clearTimeout(wheelTimer);$('#modal-root').innerHTML='';if(!$('.mobile-nav.open'))document.body.classList.remove('locked');lastFocus?.focus();}
function formatName(v){return {game:'Игра',private:'Закрытая арена',birthday:'День рождения',corporate:'Корпоратив'}[v]||v}
function consent(){return `<label class="consent"><input type="checkbox" name="consent" required><span>Согласен с <button type="button" data-action="privacy-note">условиями демо-формы</button>. Не указываю реальные персональные данные.</span></label>`}
function demoNote(){return `<div class="demo-note"><b>Демонстрационная запись.</b> Заявка сохранится в этом браузере. Сеанс не резервируется, звонка, оплаты и отправки письма не будет.</div>`}
function bookingForm(opts={}){const format=opts.format||'game';const duration=opts.duration||'60';return `<form id="booking-form" class="booking-form"><div class="format-select" role="group" aria-label="Формат посещения">${[['game','VR-игра'],['private','Закрытая арена'],['birthday','День рождения'],['corporate','Корпоратив']].map(([v,t])=>`<label><input type="radio" name="format" value="${v}"${v===format?' checked':''}><span>${t}</span></label>`).join('')}</div><fieldset class="booking-fields"><legend class="form-section-title">01 / Параметры игры</legend><div class="form-grid"><label class="field"><span>Дата посещения</span><input type="date" name="date" required min="${today()}" value="${today()}"></label><label class="field"><span>Время посещения</span><select name="time" required>${['10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00','20:00'].map(t=>`<option${t==='18:00'?' selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Количество игроков</span><select name="players">${Array.from({length:10},(_,i)=>`<option value="${i+1}"${i===3?' selected':''}>${i+1} ${i===0?'игрок':i<4?'игрока':'игроков'}</option>`).join('')}</select></label><label class="field"><span>Продолжительность</span><select name="duration">${durationChoices(format).map(([v,t])=>`<option value="${v}"${v===duration?' selected':''}>${t}</option>`).join('')}</select></label><label class="field full"><span>Сценарий</span><select name="game"><option value="">Помогите выбрать игру</option>${games.map(g=>`<option value="${g.id}"${opts.game===g.id?' selected':''}>${g.title}${g.age?' · '+g.age:''}</option>`).join('')}</select></label></div></fieldset><fieldset class="booking-fields"><legend class="form-section-title">02 / Тестовые контакты</legend><div class="form-grid"><label class="field"><span>Как тебя зовут</span><input name="name" placeholder="Например, Алексей" required maxlength="80" autocomplete="given-name"></label><label class="field"><span>Телефон</span><input type="tel" name="phone" placeholder="+7 (999) 123-45-67" required pattern="[+0-9()\s\-]{10,22}" maxlength="22" autocomplete="tel"></label><label class="field full"><span>Пожелания · необязательно</span><input name="message" placeholder="Возраст игроков, повод, особые пожелания" maxlength="500"></label></div></fieldset><div class="booking-form-bottom"><input type="hidden" name="package" value="${esc(opts.package||'')}"><div class="booking-total"><span>Стоимость <small id="estimate-unit"></small></span><strong id="booking-estimate"></strong></div><p id="booking-availability" class="muted small"></p>${demoNote()}${consent()}<div class="form-actions"><button class="btn" type="submit">Оставить заявку ${icon('arrow')}</button></div></div></form>`;}
function bookingSection(){return `<section class="section booking-section" id="booking" tabindex="-1" aria-labelledby="booking-title"><div class="wrap"><div class="eyebrow">Твоя следующая игра</div><div class="section-head"><h2 id="booking-title">ВЫБЕРИ ВРЕМЯ<br><em>ОСТАВЬ ЗАЯВКУ</em></h2><p class="booking-intro">Собери свою компанию, выбери формат<br>и сделай первый шаг в другую реальность.</p></div><div class="booking-panel">${bookingForm()}</div></div></section>`;}
function booking(opts={}){
 const section=$('#booking');
 if(section){
  if($('#modal-root').hasChildNodes())closeModal();
  const form=$('#booking-form');
  const format=$(`[name="format"][value="${opts.format||'game'}"]`,form);
  if(format)format.checked=true;
  syncDurations(opts.duration||'60');
  $('[name="game"]',form).value=opts.game||'';
  $('[name="package"]',form).value=opts.package||'';
  if(opts.day)setBookingDate(opts.day);
  updateEstimate();
  if(location.hash!=='#booking')history.pushState(null,'','#booking');
  section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
  section.focus({preventScroll:true});
  return;
 }
 modal(`<div class="eyebrow">Твоя точка входа</div><h2 id="modal-title">ГОТОВ <span class="red">ЗА ГРАНЬ?</span></h2><p class="modal-intro">Выбери формат и удобное время. Проверим, как будет выглядеть твоя заявка.</p>${bookingForm(opts)}`);
 syncDurations(opts.duration);setBookingDate(opts.day);updateEstimate();
}
function setBookingDate(day){const form=$('#booking-form');if(!form)return;let date=new Date(today()+'T12:00:00');const hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Barnaul',hour:'2-digit',hour12:false}).format(new Date()));if(hour>=20)date.setDate(date.getDate()+1);if(day){for(let i=0;i<7;i++){const isWeekend=[0,5,6].includes(date.getDay());if((day==='weekend')===isWeekend)break;date.setDate(date.getDate()+1);}}const value=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');$('[name=date]',form).value=value;if(value===today())$('[name=time]',form).value=String(Math.max(10,Math.min(20,hour+1))).padStart(2,'0')+':00';}
function durationChoices(format){return format==='birthday'||format==='corporate'?[['60','1 час'],['120','2 часа'],['180','3 часа']]:[['60','60 минут']]}
function syncDurations(preferred){const form=$('#booking-form');if(!form)return;const format=$('[name=format]:checked',form).value;const select=$('[name=duration]',form);const selected=String(preferred||select.value||60);const options=durationChoices(format);select.innerHTML=options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');select.value=options.some(([v])=>v===selected)?selected:options[0][0];}
function estimate(data){const isWeekend=[0,5,6].includes(new Date(data.date+'T12:00:00').getDay());const rateIndex=isWeekend?1:0;if(data.format==='game')return gameRates[rateIndex]*Number(data.players);if(data.format==='private')return privateRates[rateIndex];return eventRates[data.duration]?.[rateIndex]??null}
function updateEstimate(){const form=$('#booking-form');if(!form)return;const data=Object.fromEntries(new FormData(form));const price=estimate(data);$('#booking-estimate').textContent=price===null?'Уточните у администратора':money(price);$('#booking-estimate').classList.toggle('estimate-unconfirmed',price===null);$('#estimate-unit').textContent=data.format==='game'?'· за всех игроков':'· за компанию';const end=Number(data.time.split(':')[0])+Number(data.duration)/60;const time=$('[name=time]',form);time.setCustomValidity(end>22?'Сеанс должен закончиться до 22:00. Выберите более раннее время.':'');const game=games.find(g=>g.id===data.game);const count=Number(data.players);const max=game?Number(game.players.match(/–(\d+)/)?.[1]||10):10;const min=game&&game.category==='team'?2:1;const player=$('[name=players]',form);player.setCustomValidity(count>max||count<min?`Для этой игры нужно от ${min} до ${max} игроков.`:'');$('#booking-availability').textContent=end>22?'Выберите более раннее время: арена работает до 22:00.':count>max||count<min?`Для сценария «${game.title}» нужно от ${min} до ${max} игроков.`:price===null?'Цена часового праздника в ПТ–ВС уточняется у администратора.':'Сеансы и доступность показаны для примера.';}

function saveRequest(data){const list=readStore(key,[]);const random=globalThis.crypto?.randomUUID?.().slice(0,8).toUpperCase()||Math.random().toString(36).slice(2,10).toUpperCase();const r={...data,id:'ЗГ-'+random,created:new Date().toISOString(),status:'Новая'};if(!writeStore(key,[...list,r]))return null;return r;}
function success(r,type='заявка'){modal(`<div class="success"><div class="success-icon">${icon('check')}</div><div class="eyebrow" style="justify-content:center">Демо-режим</div><h2 id="modal-title">${type==='отзыв'?'ОТЗЫВ':'ЗАЯВКА'} <span class="blue">СОХРАНЁН${type==='отзыв'?'':'А'}.</span></h2><div class="reference">${esc(r.id)}</div><p>${type==='отзыв'?'Отзыв сохранён локально в этом браузере.':'Это тестовая заявка. Время не забронировано, администратор не получит уведомление и не будет звонить.'}</p><p>Посмотреть сохранённые данные можно в <a href="/za-granyu-vr-arena/admin/" style="color:var(--blue);text-decoration:underline">демо-админке</a>.</p><button class="btn btn-outline" data-action="close">Вернуться на сайт ${icon('arrow')}</button></div>`);}
function showStory(id){storyIndex=Math.max(0,games.findIndex(g=>g.id===id));const g=games[storyIndex];modal(`<div class="story-progress" role="group" aria-label="Обзоры игр">${games.map((x,i)=>`<button class="${i===storyIndex?'active':''}" data-action="story" data-id="${x.id}" aria-label="${esc(x.title)}" aria-pressed="${i===storyIndex}"></button>`).join('')}</div><div class="story-media">${g.video?`<video class="story-video" controls playsinline preload="metadata" poster="/assets/${g.image}" aria-label="Видеообзор ${g.title}"><source src="/za-granyu-vr-arena/assets/${g.video}" type="video/mp4">Ваш браузер не поддерживает видео</video>`:`<img class="story-image" src="/za-granyu-vr-arena/assets/${g.image}" alt="Обложка игры ${esc(g.title)}" width="1667" height="938">`}</div><div class="story-content"><span class="tag">${g.mode}${g.age?' · '+g.age:''}</span><h2 id="modal-title">${g.title}</h2><div class="game-meta"><span>${g.genre}</span><span>${g.players}</span></div><p>${g.description}</p><div class="story-footer"><button class="btn" data-book data-game="${g.id}" data-duration="60">Выбрать игру ${icon('arrow')}</button><button class="icon-btn" data-action="story-next" aria-label="Следующая игра">${icon('arrow')}</button></div></div>`,'story-modal');}

function callback(type='callback'){const question=type==='question';modal(`<div class="eyebrow">На связи с тобой</div><h2 id="modal-title">${question?'ТВОЙ ВОПРОС':'ПОМОЖЕМ ВЫБРАТЬ'}</h2><p class="modal-intro">Оставь тестовые контакты и пожелания, чтобы проверить форму обратной связи.</p><form id="contact-form"><div class="form-grid"><label class="field"><span>Имя</span><input name="name" required maxlength="80" placeholder="Алексей"></label><label class="field"><span>Телефон</span><input type="tel" name="phone" required pattern="[+0-9()\s\-]{10,22}" maxlength="22" placeholder="+7 (999) 123-45-67"></label><label class="field full"><span>Вопрос или пожелания</span><textarea name="message" maxlength="1000" placeholder="Помогите выбрать игру для компании из четырёх человек"></textarea></label></div>${demoNote()}${consent()}<button type="submit" class="btn" style="width:100%;margin-top:12px">Сохранить обращение ${icon('arrow')}</button></form>`);}
function reviewModal(){modal(`<div class="eyebrow">Впечатления после игры</div><h2 id="modal-title">РАССКАЖИ, <span class="red">КАК ЭТО БЫЛО</span></h2><p class="modal-intro">Демонстрационный отзыв сохранится в этом браузере.</p><form id="review-form"><div class="form-grid"><label class="field"><span>Имя</span><input name="name" required maxlength="80" placeholder="Алексей"></label><label class="field"><span>Повод</span><select name="kind"><option>Игра с друзьями</option><option>День рождения</option><option>Корпоратив</option><option>Семейное приключение</option></select></label><label class="field full"><span>Твой отзыв</span><textarea name="message" required minlength="10" maxlength="1500" placeholder="Что запомнилось больше всего?"></textarea></label></div>${demoNote()}${consent()}<button class="btn" type="submit" style="width:100%">Сохранить отзыв ${icon('arrow')}</button></form>`);}
function privacy(){modal(`<div class="eyebrow">О демонстрационных данных</div><h2 id="modal-title">УСЛОВИЯ ДЕМО-ФОРМ</h2><div class="article-modal"><p>Сайт представлен для проверки дизайна и пользовательских сценариев. Контакты и отзывы являются тестовыми. Игры и тарифы представлены по материалам арены.</p><h3>Как сохраняются данные</h3><p>При отправке формы данные остаются в localStorage текущего браузера. Они не передаются на сервер, не отправляются по электронной почте и доступны в открытой демо-админке этого браузера.</p><h3>Что вводить</h3><p>Используйте вымышленные имена и номера телефонов. Не вводите настоящие персональные данные. Удалить все заявки можно в демо-админке или через очистку данных сайта в браузере.</p><h3>Реальное бронирование</h3><p>Заявка на этом сайте не резервирует сеанс и не приводит к оплате. Перед запуском для посетителей необходимо подключить систему записи, закрытую административную часть, обработчик форм и согласованные документы оператора.</p><button class="btn btn-outline" data-action="close">Понятно ${icon('check')}</button></div>`);}
function wheel(){window.ZGPromo?.open()}
function article(i){const a=articles[i];if(!a)return;modal(`<div class="eyebrow">${a.category} / Демо-материал</div><h2 id="modal-title">${a.title}</h2><div class="article-modal"><p class="muted">${a.date}</p><img src="/za-granyu-vr-arena/assets/${a.image}" alt="${esc(a.title)}"><p>${a.body}</p><h3>${a.sub}</h3><p>${a.more}</p><button class="btn" data-book>Выбрать своё приключение ${icon('arrow')}</button></div>`,'article-modal');}
function heroSlide(dir){slide=(slide+Number(dir)+3)%3;const titles=['ВЫХОДИ<br>ЗА ГРАНЬ<span>РЕАЛЬНОГО</span>','ПРОВЕДИТЕ ПРАЗДНИК,<br>КОТОРЫЙ ВАШИ ГОСТИ<span>ТОЧНО ЗАПОМНЯТ</span>','НОВЫЙ МИР<br>НАСТОЯЩИЕ<span>ЭМОЦИИ</span>'];const subs=['<strong>НОВЫЙ ФОРМАТ КОМАНДНЫХ ИГР</strong><p>Многоуровневые карты с перемещением по этажам и зданиям с помощью порталов и лифтов</p>','VR-праздник в Барнауле для детей, взрослых, друзей, классов и компаний — с командными играми, лаунж-зоной','Окунись в мир виртуальной реальности на новой «безграничной» площадке'];$('.hero').dataset.slide=slide;$('.hero-art').style.backgroundImage='';$('#hero-title').innerHTML=titles[slide];$('#hero-sub').innerHTML=subs[slide];$('#slide-current').textContent='0'+(slide+1);}

function closeMenu(){const nav=$('.mobile-nav');nav?.classList.remove('open');const b=$('.menu-toggle');b?.setAttribute('aria-expanded','false');b?.setAttribute('aria-label','Открыть меню');if(!$('#modal-root').hasChildNodes())document.body.classList.remove('locked');}
document.addEventListener('click',e=>{
 const book=e.target.closest('[data-book]');if(book){closeMenu();booking({format:book.dataset.format,duration:book.dataset.duration,game:book.dataset.game,package:book.dataset.package,day:null});return;}
 const filter=e.target.closest('[data-filter]');if(filter){$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter))});$('#game-grid').innerHTML=games.filter(g=>filter.dataset.filter==='all'||g.category===filter.dataset.filter).map(gameCard).join('');return;}

 if(e.target.closest('.mobile-nav a'))closeMenu();
 if(e.target.classList.contains('modal-overlay')){closeModal();return;}
 const b=e.target.closest('[data-action]');if(!b)return;
 switch(b.dataset.action){
 case 'close':closeModal();break;
 case 'menu':{const open=$('.mobile-nav').classList.toggle('open');b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');document.body.classList.toggle('locked',open);break;}
 case 'story':showStory(b.dataset.id);break;
 case 'story-next':showStory(games[(storyIndex+1)%games.length].id);break;
 case 'slide':heroSlide(b.dataset.direction);break;
 case 'callback':callback();break;
 case 'review':reviewModal();break;
 case 'privacy':privacy();break;
 case 'privacy-note':toast('Демо-форма сохраняется только в этом браузере. Используйте вымышленные контакты.');break;
 case 'wheel':wheel();break;

 case 'article':article(Number(b.dataset.index));break;
 case 'social':toast('Это демонстрационная ссылка. Адрес сообщества пока не указан.');break;
 case 'export':{const blob=new Blob([JSON.stringify(readStore(key,[]),null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='za-granyu-demo-requests.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
 case 'clear-requests':modal(`<div class="eyebrow">Демо-админка</div><h2 id="modal-title">УДАЛИТЬ ДЕМО-ЗАЯВКИ?</h2><p class="modal-intro">Все заявки и отзывы, сохранённые в этом браузере, будут удалены.</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Отмена</button><button class="btn" data-action="confirm-clear">Удалить</button></div>`);break;
 case 'confirm-clear':if(writeStore(key,[])){closeModal();render();toast('Демонстрационные заявки удалены.')}break;
 }
});
document.addEventListener('change',e=>{if(e.target.closest('#booking-form')){if(e.target.name==='format'){syncDurations();$('[name=package]',$('#booking-form')).value='';}if(e.target.name==='duration')$('[name=package]',$('#booking-form')).value='';updateEstimate();}if(e.target.matches('[data-status]')){const list=readStore(key,[]);const r=list.find(x=>x.id===e.target.dataset.status);if(r){r.status=e.target.value;if(writeStore(key,list))toast('Статус сохранён.');}}});
document.addEventListener('submit',e=>{
 if(e.target.id==='booking-form'){e.preventDefault();updateEstimate();if(!e.target.reportValidity())return;const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Запись',estimate:estimate(d),game:games.find(g=>g.id===d.game)?.title||'Подбор игры'});if(r){e.target.reset();syncDurations();setBookingDate();updateEstimate();success(r);}}
 if(e.target.id==='contact-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Обратная связь'});if(r)success(r);}
 if(e.target.id==='review-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const r=saveRequest({...d,type:'Отзыв'});if(r){const grid=$('#review-grid');if(grid)grid.insertAdjacentHTML('afterbegin',reviewHTML({name:d.name,text:d.message,kind:d.kind},false));success(r,'отзыв');}}
 if(e.target.id==='config-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(writeStore('zg-demo-config',d)){Object.assign(config,d);toast('Фоны сохранены. Откройте нужную страницу.');}}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').hasChildNodes())closeModal();else closeMenu();}if(e.key==='Tab'&&$('.modal')){const nodes=$$('button:not([disabled]),a[href],input,select,textarea,[tabindex="0"]',$('.modal')).filter(x=>x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='ArrowRight'&&$('.story-modal'))showStory(games[(storyIndex+1)%games.length].id);if(e.key==='ArrowLeft'&&$('.story-modal'))showStory(games[(storyIndex+games.length-1)%games.length].id);});
window.addEventListener('resize',()=>{if(innerWidth>1000)closeMenu();});
if(location.hash)requestAnimationFrame(()=>$(location.hash)?.scrollIntoView());
